//! Rust translation of `sdk/lib/vcruntime/amd64/longjmp.c` — x64 `longjmp`.
//!
//! amd64-only, ntdll.dll-proper only. The register save/restore halves
//! (`setjmp` / `_setjmpex` / `__intrinsic_setjmp*` / `__longjmp_noframe`) stay
//! in pre-expanded asm (`ntdll-cargo/data/asm/{setjmp,longjmp_noframe}-amd64.s`,
//! generated by `tools/gen_ntdll_asm.py`); this is just the C glue that drives
//! `RtlUnwind` when the jump buffer captured an SEH frame, then tail-calls the
//! frameless restore.
//!
//! Gated to `target_arch = "x86_64"` + non-`vista`: i386/arm64 ntdll never
//! reference setjmp/longjmp (the cmake `libsetjmp.a` is dead there), and
//! `ntdll_vista.dll` doesn't link setjmp at all — amd64 `ntdll.dll` is the only
//! consumer. Replaces the cmake `libsetjmp.a` reuse on amd64.

use core::ffi::c_int;
use core::mem::zeroed;
use core::ptr::addr_of_mut;
use ntdll_sys::nt::*;

/// `STATUS_LONGJUMP` (0x8000_0026) — not in the bindgen surface.
const STATUS_LONGJUMP: u32 = 0x8000_0026;

/// Minimal mirror of the amd64 `_JUMP_BUFFER` (vcruntime/setjmp.h): `longjmp`
/// only reads `Frame` (0x00) and `Rip` (0x50). The nine callee-saved GPRs in
/// between (Rbx, Rsp, Rbp, Rsi, Rdi, R12–R15) — and the XMM/MxCsr tail — are
/// the asm's concern, restored by `__longjmp_noframe`.
#[repr(C)]
struct JumpBuffer {
    Frame: u64,
    _saved_gprs: [u64; 9],
    Rip: u64,
}

extern "C" {
    /// amd64 asm (`__longjmp_noframe.s`): restore the saved context; no return.
    fn __longjmp_noframe(buf: *const JumpBuffer, value: c_int) -> !;
}

/// `longjmp` (`__cdecl`) — see `vcruntime/amd64/longjmp.c`. If the buffer
/// captured an SEH frame, unwind to it (raising `STATUS_LONGJUMP`) before the
/// frameless register restore.
#[no_mangle]
pub unsafe extern "C" fn longjmp(buf: *mut JumpBuffer, value: c_int) -> ! {
    // Ensure the value setjmp returns is non-zero.
    let value = if value == 0 { 1 } else { value };

    if (*buf).Frame != 0 {
        let mut exception_record: EXCEPTION_RECORD = zeroed();
        exception_record.ExceptionCode = STATUS_LONGJUMP as _;
        exception_record.NumberParameters = 1;
        exception_record.ExceptionInformation[0] = buf as usize as _;

        RtlUnwind(
            (*buf).Frame as PVOID,
            (*buf).Rip as PVOID,
            addr_of_mut!(exception_record),
            value as ULONG_PTR as PVOID,
        );
    }

    __longjmp_noframe(buf, value)
}
